package com.hms.dao.impl;
import com.hms.config.DatabaseConnection; import com.hms.dao.BillingDao; import com.hms.model.Billing; import java.sql.*; import java.math.BigDecimal; import java.util.*;
public class BillingDaoImpl implements BillingDao { private Billing map(ResultSet r)throws SQLException{return new Billing(r.getInt("bill_id"),r.getInt("appointment_id"),r.getString("patient_name"),r.getString("doctor_name"),r.getTimestamp("visit_date").toLocalDateTime(),r.getBigDecimal("consultation_fee"),r.getBigDecimal("service_fee"),r.getBigDecimal("discount"),r.getBigDecimal("tax"),r.getBigDecimal("total_amount"),r.getString("payment_status"),r.getBigDecimal("paid_amount"));}
 public List<Billing> findAll()throws SQLException{List<Billing> out=new ArrayList<>();String q="SELECT b.*,a.appointment_date visit_date,p.full_name patient_name,d.full_name doctor_name FROM billing b JOIN appointments a ON a.appointment_id=b.appointment_id JOIN patients p ON p.patient_id=a.patient_id JOIN doctors d ON d.doctor_id=a.doctor_id ORDER BY b.bill_id DESC";try(Connection c=DatabaseConnection.getConnection();PreparedStatement p=c.prepareStatement(q);ResultSet r=p.executeQuery()){while(r.next())out.add(map(r));}return out;}
 public Billing save(Billing b)throws SQLException{String q="INSERT INTO billing(appointment_id,consultation_fee,service_fee,discount,tax,payment_status,paid_amount) VALUES(?,?,?,?,?,?,?)";try(Connection c=DatabaseConnection.getConnection();PreparedStatement p=c.prepareStatement(q,Statement.RETURN_GENERATED_KEYS)){p.setInt(1,b.appointmentId());p.setBigDecimal(2,b.consultationFee());p.setBigDecimal(3,b.serviceFee());p.setBigDecimal(4,b.discount());p.setBigDecimal(5,b.tax());p.setString(6,b.paymentStatus());p.setBigDecimal(7,b.paidAmount());p.executeUpdate();try(ResultSet k=p.getGeneratedKeys()){return new Billing(k.next()?k.getInt(1):0,b.appointmentId(),b.patientName(),b.doctorName(),b.visitDate(),b.consultationFee(),b.serviceFee(),b.discount(),b.tax(),b.totalAmount(),b.paymentStatus(),b.paidAmount());}}}
}
